import type { Readable } from 'node:stream';

import { Router } from 'express';
import { pipeline } from 'node:stream/promises';

import { getObject } from '../storage.ts';

export const mediaRoutes = Router();

// Keys generated by the server look like "folder/name.ext". Anything else is rejected.
const KEY_REGEX = /^[a-z]+\/[a-zA-Z0-9-]+\.[a-z0-9]+$/;

// GET /api/media/*key
mediaRoutes.get('/*key', async (req, res) => {
  const key = (req.params.key as string[]).join('/');

  if (!KEY_REGEX.test(key)) {
    res.status(404).json({ error: 'File not found.' });
    return;
  }

  let object;
  try {
    object = await getObject(key);
  } catch (error) {
    if ((error as { name?: string; }).name === 'NoSuchKey') {
      res.status(404).json({ error: 'File not found.' });
      return;
    }
    throw error;
  }

  if (object.ContentType) {
    res.type(object.ContentType);
  }
  if (object.ContentLength !== undefined) {
    res.setHeader('Content-Length', object.ContentLength);
  }

  // Keys are unique, so a file never changes: browsers can cache it for a long time.
  res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
  // Never let a stored file run scripts or be interpreted as another type.
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Content-Security-Policy', "default-src 'none'; sandbox");

  await pipeline(object.Body as Readable, res);
});
